const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-type]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.type!==b.dataset.filter)}));document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const blob=new Blob(['WONDERFUL PRINT — PROJECT BRIEF\n\nประเภทงาน: '+data.get('service')+'\nรายละเอียด: '+data.get('details')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wonderful-print-project.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='ดาวน์โหลดสรุปงานแล้ว ข้อมูลยังไม่ได้ส่งถึงบริษัท'});document.querySelector('#year').textContent=new Date().getFullYear();
